  const [form, setForm] = useState({ title: '', achievedAt: '', description: '', issuer: '', achievementTypeId: '', levelCode: '' }), [editing, setEditing] = useState(null), [error, setError] = useState(null), [expanded, setExpanded] = useState(null), [files, setFiles] = useState([]);
