  async function openFiles(id) { try { setExpanded(id); setFiles(array(await api(`/achievements/${id}/evidences`))); } catch (err) { setError(err); } }
  async function upload(e, id) { const file = e.target.files?.[0]; if (!file) return; const data = new FormData(); data.append('file', file); try { await api(`/achievements/${id}/evidences`, 'POST', data); await openFiles(id); await state.reload(); } catch (err) { setError(err); } e.target.value = ''; }
  async function extract(e) { const file = e.target.files?.[0]; if (!file) return; const data = new FormData(); data.append('file', file); try { const result = await api('/achievements/ai-extract', 'POST', data); if (result.data) setForm(old => ({ ...old, title: result.data.title || old.title, achievedAt: result.data.issueDate || old.achievedAt, issuer: result.data.issuer || old.issuer })); else setError(new Error(result.message || 'Không thể trích xuất tự động. Hãy nhập thông tin thủ công.')); } catch (err) { setError(err); } e.target.value = ''; }
  async function download(file) { try { const blob = await api(`/evidence-files/${file.id}/download`, 'GET', undefined, { responseType: 'blob' }); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = file.originalFileName; link.click(); URL.revokeObjectURL(link.href); } catch (err) { setError(err); } }
