  function begin(item) { setError(null); if (item) { setEditing(item.id); setAttributesJson(JSON.stringify(item.attributes || {},null,2)); setForm({ title:item.title || '',achievedAt:item.achievedAt?.slice(0,10) || '',description:item.description || '',issuer:item.issuer || '',achievementTypeId:item.achievementTypeId || '',levelCode:item.levelCode || '' }); } else reset(); setShowForm(true); }
  const addButton = <button type="button" className={button} onClick={() => begin()}><Plus size={17} aria-hidden="true" />Thêm thành tích</button>;
